    this.pos = new THREE.Vector3(0, 0, 0);
    this.yaw = 0;
    this.pitch = 0;
    this.health = 100;
    this.armor = 0;
    this.money = 0; // the match sets the purse
    this.alive = true;
    this.crouch = false;
    this.weapons = { primary: null, sidearm: makeWeaponState('p9') };
    this.active = 'sidearm';
    this.fireTimer = 0;
    this.reloadTimer = 0;
    this.bloom = 0;
    this.moving = false;
    this.keys = new Set();
